/**
 * Scripts vidéo de formation (un par maladie/événement), à intégrer sous le contenu de
 * chaque module du briefing (assets/briefing-data.js) : exemple de cas concret, signes par
 * partie du corps (avec pictogrammes animés), définition du cas alerte, transmission,
 * prévention, CAT du RC, message de clôture — plus un bouton de lecture vocale (Web Speech
 * API) pour écouter le script ou filmer un RC en train de le lire face caméra.
 *
 * BRIEFING_VIDEO_BODIES[id]  : HTML du script (mêmes id que BRIEFING_MODULES).
 * BRIEFING_VIDEO_TTS[id]     : texte brut correspondant, pour la lecture vocale.
 * Rendu et lecture vocale gérés par assets/briefing-videos.js.
 */
const BRIEFING_VIDEO_BODIES = {
  anthrax: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('anthrax')\" id=\"tts-btn-anthrax\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Dans un village de l&#x27;Atacora, Toussaint élève des bœufs. Un matin, une de ses vaches meurt d&#x27;un coup et gonfle très vite. Sans faire inspecter la viande, il la découpe pour la vendre au marché. Trois jours après, une petite plaie noire apparaît sur sa main et grossit, avec de la fièvre.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"🔴 Éruption cutanée\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-eruption\">\n    <ellipse cx=\"30\" cy=\"32\" rx=\"18\" ry=\"20\" fill=\"#fde3e0\"/>\n    <circle cx=\"20\" cy=\"20\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d1\"/>\n    <circle cx=\"34\" cy=\"16\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d2\"/>\n    <circle cx=\"42\" cy=\"28\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d3\"/>\n    <circle cx=\"18\" cy=\"36\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d4\"/>\n    <circle cx=\"30\" cy=\"42\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d5\"/>\n    <circle cx=\"40\" cy=\"42\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d6\"/>\n  </svg><span class=\"picto-label\">🔴 Éruption cutanée</span></div><div class=\"picto-item\" title=\"🤮 Vomissements\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-vomissement\">\n    <circle cx=\"26\" cy=\"30\" r=\"14\" fill=\"#e0f2d8\"/>\n    <circle cx=\"21\" cy=\"27\" r=\"2\" fill=\"#1c1c2e\"/>\n    <path d=\"M20 36 q6 -4 12 0\" stroke=\"#1c1c2e\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-vwave\" d=\"M40 34 q4 4 2 10\" stroke=\"#7cb342\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/>\n  </svg><span class=\"picto-label\">🤮 Vomissements</span></div><div class=\"picto-item\" title=\"🫁 Difficulté à respirer\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-respiration\">\n    <path class=\"picto-lung\" d=\"M24 14 q-10 4 -10 20 q0 10 8 10 q4 0 4 -8 v-22 z\" fill=\"#f3c6c6\"/>\n    <path class=\"picto-lung picto-lung2\" d=\"M36 14 q10 4 10 20 q0 10 -8 10 q-4 0 -4 -8 v-22 z\" fill=\"#f3c6c6\"/>\n  </svg><span class=\"picto-label\">🫁 Difficulté à respirer</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Sur la peau</strong> — Un petit bouton apparaît (souvent sur la main ou le bras), il devient noir comme du charbon et gonfle autour. Ça ne fait pas très mal, mais ça grossit vite.</li><li><strong>Dans le ventre</strong> — La personne a mal au ventre, vomit, n&#x27;a plus faim, et a de la fièvre.</li><li><strong>Pour respirer</strong> — La personne a du mal à respirer, comme si l&#x27;air manquait, avec une très forte fièvre.</li><li><strong>Dans la tête</strong> — La fièvre monte d&#x27;un coup, le corps se met à trembler fort (on appelle ça des convulsions), et la personne peut perdre connaissance.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : toute personne qui travaille avec des animaux (éleveur, boucher, agriculteur) et qui a une plaie noire sur la peau, ou une forte fièvre avec le corps qui tremble, ou du mal à respirer.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne présentant une plaie noirâtre sur la peau, OU une forte fièvre avec convulsions, OU une difficulté à respirer — surtout si elle travaille avec des animaux (éleveurs, bouchers, agriculteurs).\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🥩 Manger de la viande contaminée</li><li>💨 Respirer des poussières infectées (champs)</li><li>🤝 Toucher des animaux ou tissues infectés</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>💉 Vacciner les animaux (herbivores, porcs)</li><li>🔍 Inspecter la viande avant de la manger ou vendre</li><li>🚧 Interdire l&#x27;accès aux champs contaminés</li><li>😷 Porter un masque lors des travaux à risque</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise les éleveurs, bouchers et agriculteurs sur les modes de transmission, les symptômes et les moyens de prévention. Rappelle la nécessité d&#x27;inspecter toute viande avant de la consommer ou la vendre.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  covid: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('covid')\" id=\"tts-btn-covid\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">À Cotonou, dans un quartier populaire, Sika a de la fièvre depuis 2 jours. Elle tousse beaucoup, a mal à la gorge, et elle ne sent plus l&#x27;odeur de son plat préféré.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"😮‍💨 Toux\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-toux\">\n    <circle cx=\"26\" cy=\"32\" r=\"14\" fill=\"#fde3e0\"/>\n    <circle cx=\"21\" cy=\"29\" r=\"2\" fill=\"#1c1c2e\"/>\n    <path d=\"M20 39 q6 4 12 0\" stroke=\"#1c1c2e\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-puff\" d=\"M40 26 q6 -2 10 -6\" stroke=\"#6b7280\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path class=\"picto-puff picto-puff2\" d=\"M40 32 q8 0 14 -2\" stroke=\"#6b7280\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path class=\"picto-puff picto-puff3\" d=\"M40 38 q6 4 10 6\" stroke=\"#6b7280\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/>\n  </svg><span class=\"picto-label\">😮‍💨 Toux</span></div><div class=\"picto-item\" title=\"💩 Diarrhée\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-diarrhee\">\n    <ellipse cx=\"30\" cy=\"46\" rx=\"16\" ry=\"6\" fill=\"#d9e6f2\"/>\n    <rect x=\"16\" y=\"10\" width=\"28\" height=\"4\" fill=\"#8ba3bd\"/>\n    <path d=\"M18 14 v14\" stroke=\"#8ba3bd\" stroke-width=\"3\"/>\n    <path d=\"M42 14 v14\" stroke=\"#8ba3bd\" stroke-width=\"3\"/>\n    <path class=\"picto-drop\" d=\"M30 20 q4 6 0 10 q-4 -4 0 -10 z\" fill=\"#1565c0\"/>\n    <path class=\"picto-drop picto-drop2\" d=\"M22 22 q3 5 0 8 q-3 -3 0 -8 z\" fill=\"#1565c0\"/>\n    <path class=\"picto-drop picto-drop3\" d=\"M38 22 q3 5 0 8 q-3 -3 0 -8 z\" fill=\"#1565c0\"/>\n  </svg><span class=\"picto-label\">💩 Diarrhée</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre</strong> — Le corps est chaud, on transpire ou on frissonne.</li><li><strong>Toux et gorge</strong> — La personne tousse souvent et a mal quand elle avale.</li><li><strong>Nez</strong> — Le nez coule ou est bouché, comme un gros rhume.</li><li><strong>Odorat et goût</strong> — La personne ne sent plus les odeurs et ne reconnaît plus le goût de la nourriture.</li><li><strong>Ventre</strong> — Parfois, la personne a la diarrhée (selles liquides).</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : fièvre + au moins un de ces signes (toux, rhume, mal de gorge, perte de l&#x27;odorat ou du goût, diarrhée).</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne ayant de la fièvre ET au moins un de ces signes: toux, rhume, éternuements, mal de gorge, difficulté à respirer, perte de l&#x27;odorat/goût, diarrhée.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>💨 Postillons et gouttelettes en parlant, toussant, éternuant</li><li>🤚 Toucher des surfaces contaminées puis se toucher le visage</li><li>👁️ Contact avec les yeux, le nez ou la bouche</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🧼 Se laver les mains souvent à l&#x27;eau et au savon</li><li>😷 Porter un masque hors de la maison</li><li>📏 Garder 1 mètre de distance avec les autres</li><li>🤧 Tousser dans le coude, pas dans la main</li><li>🚫 Éviter les grands rassemblements</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur les gestes barrières, surveille les ménages, communique le numéro 136, et identifie les personnes revenues de voyage récemment.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  cholera: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('cholera')\" id=\"tts-btn-cholera\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Après un mariage au village où l&#x27;eau du puits n&#x27;était pas propre, Akpédjè commence soudainement à aller aux toilettes très souvent, avec des selles toutes liquides comme de l&#x27;eau de riz. Elle est très fatiguée et a très soif.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"💩 Diarrhée\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-diarrhee\">\n    <ellipse cx=\"30\" cy=\"46\" rx=\"16\" ry=\"6\" fill=\"#d9e6f2\"/>\n    <rect x=\"16\" y=\"10\" width=\"28\" height=\"4\" fill=\"#8ba3bd\"/>\n    <path d=\"M18 14 v14\" stroke=\"#8ba3bd\" stroke-width=\"3\"/>\n    <path d=\"M42 14 v14\" stroke=\"#8ba3bd\" stroke-width=\"3\"/>\n    <path class=\"picto-drop\" d=\"M30 20 q4 6 0 10 q-4 -4 0 -10 z\" fill=\"#1565c0\"/>\n    <path class=\"picto-drop picto-drop2\" d=\"M22 22 q3 5 0 8 q-3 -3 0 -8 z\" fill=\"#1565c0\"/>\n    <path class=\"picto-drop picto-drop3\" d=\"M38 22 q3 5 0 8 q-3 -3 0 -8 z\" fill=\"#1565c0\"/>\n  </svg><span class=\"picto-label\">💩 Diarrhée</span></div><div class=\"picto-item\" title=\"😴 Fatigue\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fatigue\">\n    <circle cx=\"26\" cy=\"32\" r=\"14\" fill=\"#e3f0ff\"/>\n    <path d=\"M20 32 h6\" stroke=\"#1c1c2e\" stroke-width=\"2\"/>\n    <path d=\"M32 32 h6\" stroke=\"#1c1c2e\" stroke-width=\"2\"/>\n    <text x=\"40\" y=\"20\" font-size=\"10\" fill=\"#1565c0\" class=\"picto-zzz z1\">z</text>\n    <text x=\"46\" y=\"14\" font-size=\"8\" fill=\"#1565c0\" class=\"picto-zzz z2\">z</text>\n    <text x=\"50\" y=\"9\" font-size=\"6\" fill=\"#1565c0\" class=\"picto-zzz z3\">z</text>\n  </svg><span class=\"picto-label\">😴 Fatigue</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Selles (aller aux toilettes)</strong> — La personne va aux toilettes 3 fois ou plus en une seule journée, avec des selles complètement liquides, comme de l&#x27;eau — pas des selles normales.</li><li><strong>Fatigue et soif</strong> — La personne se sent très faible, très fatiguée, et a énormément soif car son corps perd beaucoup d&#x27;eau.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : 3 selles liquides ou plus en une journée. C&#x27;est très grave et très contagieux — un seul cas suffit pour alerter tout de suite, il ne faut pas attendre d&#x27;autres cas.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne ayant 3 selles liquides ou plus en 24 heures. ⚠️ Un seul cas suspect = cas alerte !\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🥤 Eau contaminée</li><li>🍽️ Aliments souillés (non lavés ou mal cuits)</li><li>🤝 Contact avec une personne infectée (selles)</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🧼 Se laver les mains à l&#x27;eau et au savon avant de manger et après les toilettes</li><li>🚽 Utiliser des latrines pour faire ses besoins</li><li>💧 Traiter l&#x27;eau de boisson avant de la consommer</li><li>🍳 Bien cuire les aliments</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur le lavage des mains, encourage le traitement de l&#x27;eau de boisson, et promeut l&#x27;utilisation des latrines dans chaque ménage.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  dengue: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('dengue')\" id=\"tts-btn-dengue\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">En saison des pluies, près d&#x27;une flaque d&#x27;eau où les moustiques pondent, Comlan attrape d&#x27;un coup une très forte fièvre, avec des douleurs partout dans le corps (muscles et articulations) comme s&#x27;il avait été battu.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"🤕 Maux de tête\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-maux\">\n    <circle cx=\"30\" cy=\"30\" r=\"16\" fill=\"#fde3e0\"/>\n    <path class=\"picto-bolt\" d=\"M32 14 l-6 12 h6 l-6 12\" stroke=\"#e67e22\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  </svg><span class=\"picto-label\">🤕 Maux de tête</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre</strong> — Elle arrive d&#x27;un coup et monte très haut.</li><li><strong>Douleurs du corps</strong> — Les muscles et les articulations (genoux, coudes, poignets) font très mal, comme après un gros effort ou une bagarre.</li><li><strong>Tête et yeux</strong> — Souvent, mal à la tête et derrière les yeux.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : fièvre soudaine + fortes douleurs dans le corps, surtout en période où il y a beaucoup de moustiques.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne présentant une forte fièvre soudaine avec des douleurs musculaires et articulaires importantes, surtout en saison pluvieuse (période des moustiques).\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <p>🦟 Piqûre du moustique Aedes aegypti (moustique tigre) infecté → Ce moustique pique surtout le matin et le soir. Il pond ses œufs dans les eaux stagnantes (vieux pneus, canaris, bidons).</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🪣 Éliminer les eaux stagnantes autour des maisons</li><li>🛏️ Dormir sous moustiquaire imprégnée (MIILD)</li><li>🪟 Mettre des grillages aux portes et fenêtres</li><li>🌿 Débroussailler autour des maisons</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur les moustiques et les eaux stagnantes. Encourage l&#x27;utilisation des moustiquaires dans tous les foyers.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  fj: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('fj')\" id=\"tts-btn-fj\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Blaise, agriculteur qui n&#x27;a jamais été vacciné, a une fièvre qui arrive d&#x27;un coup. Quelques jours après, ses yeux et sa peau deviennent jaunes.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"🟡 Jaunisse\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-jaunisse\">\n    <circle cx=\"30\" cy=\"30\" r=\"18\" fill=\"#f9d94a\" class=\"picto-face\"/>\n    <circle cx=\"24\" cy=\"27\" r=\"2\" fill=\"#1c1c2e\"/>\n    <circle cx=\"36\" cy=\"27\" r=\"2\" fill=\"#1c1c2e\"/>\n    <path d=\"M24 37 q6 4 12 0\" stroke=\"#1c1c2e\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🟡 Jaunisse</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre</strong> — Elle commence brutalement, d&#x27;un seul coup.</li><li><strong>Yeux et peau</strong> — Après quelques jours, le blanc des yeux devient jaune, puis la peau aussi devient jaune. On appelle ça la jaunisse.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : fièvre soudaine suivie, dans les 14 jours, d&#x27;une jaunisse (yeux et peau jaunes).</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne ayant une fièvre soudaine suivie d&#x27;une jaunisse (yeux et peau jaunes) dans les 14 jours après les premiers signes.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🦟 Piqûre de moustique infecté (genre Aedes)</li><li>🐒 Peut venir des singes en forêt (via moustiques)</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>💉 Se faire vacciner contre la fièvre jaune</li><li>🪣 Éliminer les gîtes à moustiques (eaux stagnantes)</li><li>🛏️ Dormir sous moustiquaire (MIILD)</li><li>🪟 Grillages aux portes et fenêtres</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur la vaccination et la lutte contre les moustiques. Encourage chaque famille à dormir sous moustiquaire.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  grippe: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('grippe')\" id=\"tts-btn-grippe\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Dans un village d&#x27;éleveurs de volailles, plusieurs poules meurent d&#x27;un coup sans raison. Quelques jours après, Fifamè, qui s&#x27;occupe des poules, a de la fièvre, tousse et a du mal à respirer.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"😮‍💨 Toux\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-toux\">\n    <circle cx=\"26\" cy=\"32\" r=\"14\" fill=\"#fde3e0\"/>\n    <circle cx=\"21\" cy=\"29\" r=\"2\" fill=\"#1c1c2e\"/>\n    <path d=\"M20 39 q6 4 12 0\" stroke=\"#1c1c2e\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-puff\" d=\"M40 26 q6 -2 10 -6\" stroke=\"#6b7280\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path class=\"picto-puff picto-puff2\" d=\"M40 32 q8 0 14 -2\" stroke=\"#6b7280\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path class=\"picto-puff picto-puff3\" d=\"M40 38 q6 4 10 6\" stroke=\"#6b7280\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/>\n  </svg><span class=\"picto-label\">😮‍💨 Toux</span></div><div class=\"picto-item\" title=\"🫁 Difficulté à respirer\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-respiration\">\n    <path class=\"picto-lung\" d=\"M24 14 q-10 4 -10 20 q0 10 8 10 q4 0 4 -8 v-22 z\" fill=\"#f3c6c6\"/>\n    <path class=\"picto-lung picto-lung2\" d=\"M36 14 q10 4 10 20 q0 10 -8 10 q-4 0 -4 -8 v-22 z\" fill=\"#f3c6c6\"/>\n  </svg><span class=\"picto-label\">🫁 Difficulté à respirer</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre et toux</strong> — La personne a de la fièvre et tousse beaucoup.</li><li><strong>Pour respirer</strong> — Elle a du mal à respirer, comme si elle manquait d&#x27;air.</li><li><strong>Lien avec les volailles</strong> — Ce signe apparaît après avoir touché ou mangé des poules ou canards malades ou morts.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : fièvre + toux + difficulté à respirer, après un contact avec des volailles mortes ou malades.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne présentant fièvre + toux + difficultés respiratoires après avoir eu contact avec des volailles mortes ou malades, ou après avoir mangé de la volaille mal cuite.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🐔 Contact avec les selles ou sécrétions de volailles infectées</li><li>🍗 Consommer de la volaille ou eau contaminée</li><li>👕 Toucher des vêtements ou équipements contaminés</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🔒 Tenir les volailles loin des oiseaux sauvages</li><li>🧹 Garder les poulaillers propres</li><li>📢 Signaler toute mort suspecte de volaille</li><li>🍗 Bien cuire les volailles avant de les manger</li><li>🧼 Se laver les mains après tout contact avec les volailles</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise les éleveurs et commerçants de volailles sur les règles d&#x27;hygiène. Surveille et signale immédiatement toute mort massive de volaille dans le quartier.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  hanta: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('hanta')\" id=\"tts-btn-hanta\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Un cultivateur qui range son grenier plein de rats et de leurs crottes commence, quelques semaines après, à avoir de la fièvre et des courbatures partout dans le corps.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"😴 Fatigue\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fatigue\">\n    <circle cx=\"26\" cy=\"32\" r=\"14\" fill=\"#e3f0ff\"/>\n    <path d=\"M20 32 h6\" stroke=\"#1c1c2e\" stroke-width=\"2\"/>\n    <path d=\"M32 32 h6\" stroke=\"#1c1c2e\" stroke-width=\"2\"/>\n    <text x=\"40\" y=\"20\" font-size=\"10\" fill=\"#1565c0\" class=\"picto-zzz z1\">z</text>\n    <text x=\"46\" y=\"14\" font-size=\"8\" fill=\"#1565c0\" class=\"picto-zzz z2\">z</text>\n    <text x=\"50\" y=\"9\" font-size=\"6\" fill=\"#1565c0\" class=\"picto-zzz z3\">z</text>\n  </svg><span class=\"picto-label\">😴 Fatigue</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre</strong> — Le corps devient chaud.</li><li><strong>Douleurs et fatigue</strong> — La personne a mal partout dans le corps et se sent très faible.</li><li><strong>Lien avec les rats</strong> — Ce signe apparaît après avoir été en contact avec des rats, leurs crottes, ou la poussière d&#x27;un endroit où il y a des rats (grenier, grange).</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : fièvre + un autre signe, chez une personne qui a été en contact avec des rats dans les 45 derniers jours.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne ayant de la fièvre + au moins un signe (douleurs musculaires, maux de tête, problèmes digestifs, difficultés respiratoires) ET dans les 45 derniers jours: contact avec des rongeurs, séjour en zone à risque, ou contact avec un cas confirmé.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🐀 Contact avec l&#x27;urine, les selles ou la salive de rongeurs infectés</li><li>🫁 Respirer des poussières contaminées par des rongeurs</li><li>🩸 Morsure de rongeur</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🏠 Garder la maison propre, boucher les trous où les rats peuvent entrer</li><li>🥣 Protéger les aliments contre les rongeurs</li><li>💧 Humidifier la zone avant de nettoyer (ne pas balayer à sec)</li><li>🧼 Se laver régulièrement les mains à l&#x27;eau et au savon</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur les dangers des rongeurs et l&#x27;importance de maintenir les habitations propres et sans rats.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  lassa: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('lassa')\" id=\"tts-btn-lassa\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Dans une maison où les rats courent partout et grignotent la nourriture, Mariam tombe malade : elle a de la fièvre, mal à la tête, et elle commence à saigner du nez sans raison.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"🩸 Saignement\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-saignement\">\n    <path class=\"picto-blooddrop\" d=\"M30 10 C40 26 44 34 34 42 C28 47 22 42 22 36 C22 28 24 22 30 10 Z\" fill=\"#c0392b\"/>\n  </svg><span class=\"picto-label\">🩸 Saignement</span></div><div class=\"picto-item\" title=\"😴 Fatigue\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fatigue\">\n    <circle cx=\"26\" cy=\"32\" r=\"14\" fill=\"#e3f0ff\"/>\n    <path d=\"M20 32 h6\" stroke=\"#1c1c2e\" stroke-width=\"2\"/>\n    <path d=\"M32 32 h6\" stroke=\"#1c1c2e\" stroke-width=\"2\"/>\n    <text x=\"40\" y=\"20\" font-size=\"10\" fill=\"#1565c0\" class=\"picto-zzz z1\">z</text>\n    <text x=\"46\" y=\"14\" font-size=\"8\" fill=\"#1565c0\" class=\"picto-zzz z2\">z</text>\n    <text x=\"50\" y=\"9\" font-size=\"6\" fill=\"#1565c0\" class=\"picto-zzz z3\">z</text>\n  </svg><span class=\"picto-label\">😴 Fatigue</span></div><div class=\"picto-item\" title=\"🤕 Maux de tête\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-maux\">\n    <circle cx=\"30\" cy=\"30\" r=\"16\" fill=\"#fde3e0\"/>\n    <path class=\"picto-bolt\" d=\"M32 14 l-6 12 h6 l-6 12\" stroke=\"#e67e22\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  </svg><span class=\"picto-label\">🤕 Maux de tête</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre et fatigue</strong> — La personne a de la fièvre, mal à la tête, et se sent très faible.</li><li><strong>Saignements</strong> — Du sang sort du nez, des gencives, ou ailleurs, sans blessure — c&#x27;est un signe grave.</li><li><strong>Lien avec les rats ou un malade</strong> — Ce signe apparaît après un contact avec des rats, leur urine ou leurs crottes, ou après avoir touché une personne déjà malade de cette fièvre.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : des signes évocateurs, OU un saignement qui n&#x27;a pas d&#x27;explication, OU un contact avec un malade dans les 21 derniers jours.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne présentant les signes ci-dessus, OU toute personne avec des saignements inexpliqués, OU ayant eu contact avec un cas suspect de Lassa dans les 21 derniers jours.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🐀 Contact avec les excréments, urine ou salive de rat multimamelles (Mastomys)</li><li>🩸 Contact avec le sang, sueur, selles ou liquides biologiques d&#x27;un malade</li><li>⚰️ Contact avec le corps d&#x27;une personne décédée de Lassa</li><li>🦇 Contact avec chauves-souris ou singes morts en période d&#x27;épidémie</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🧼 Lavage systématique des mains à l&#x27;eau et au savon</li><li>🐀 Dératiser les maisons, protéger les aliments contre les rats</li><li>🚫 Ne pas toucher les personnes malades ou décédées sans protection</li><li>🦇 Ne pas manipuler ni consommer les chauves-souris ou singes</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur les rats, les liquides biologiques des malades et la conduite à tenir. Encourage la dératisation dans chaque ménage.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  meningite: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('meningite')\" id=\"tts-btn-meningite\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">En saison sèche (harmattan), Kokou a une très forte fièvre. Son cou est tout raide et dur : il n&#x27;arrive plus à pencher la tête en avant pour toucher sa poitrine avec le menton.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre</strong> — Elle est très forte.</li><li><strong>Le cou</strong> — Le cou devient raide et dur, la personne ne peut plus baisser la tête vers l&#x27;avant. C&#x27;est le signe le plus important à reconnaître.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : fièvre ET nuque raide (le cou ne plie plus vers l&#x27;avant). C&#x27;est une urgence — il faut référer très vite.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne présentant de la fièvre ET une nuque raide.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>💨 Gouttelettes respiratoires (toux, éternuements, postillons)</li><li>🏠 Surpopulation dans les logements</li><li>🌵 Saison sèche (harmattan) favorise la transmission</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>💉 Vaccination antiméningococcique</li><li>🧼 Hygiène des mains et hygiène respiratoire</li><li>🏠 Éviter la surpopulation dans les logements</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Mène des activités de sensibilisation sur la méningite. Encourage la vaccination et le respect des règles d&#x27;hygiène respiratoire.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  mpox: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('mpox')\" id=\"tts-btn-mpox\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Après avoir chassé et préparé un animal de brousse, Idrissou remarque un bouton bizarre sur sa peau, qui ne ressemble pas à un bouton normal et qui ne guérit pas comme d&#x27;habitude.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"🔴 Éruption cutanée\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-eruption\">\n    <ellipse cx=\"30\" cy=\"32\" rx=\"18\" ry=\"20\" fill=\"#fde3e0\"/>\n    <circle cx=\"20\" cy=\"20\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d1\"/>\n    <circle cx=\"34\" cy=\"16\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d2\"/>\n    <circle cx=\"42\" cy=\"28\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d3\"/>\n    <circle cx=\"18\" cy=\"36\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d4\"/>\n    <circle cx=\"30\" cy=\"42\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d5\"/>\n    <circle cx=\"40\" cy=\"42\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d6\"/>\n  </svg><span class=\"picto-label\">🔴 Éruption cutanée</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Sur la peau</strong> — Un ou plusieurs boutons ou plaies apparaissent sur la peau, souvent au visage, aux mains ou aux parties intimes. Ils peuvent ressembler à des cloques ou des croûtes qui ne guérissent pas vite.</li><li><strong>Fièvre (parfois)</strong> — Il peut y avoir de la fièvre avant ou en même temps que les boutons, mais pas toujours.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : n&#x27;importe quelle éruption de la peau qu&#x27;on ne peut pas expliquer, avec ou sans fièvre — même un seul bouton suffit pour alerter, il ne faut pas attendre d&#x27;en voir plusieurs.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne présentant une éruption cutanée (boutons) inexpliquée sur le corps, avec ou sans fièvre. ⚠️ Même une seule lésion compte !\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🤝 Contact peau à peau (toucher, rapports sexuels)</li><li>💋 Contact bouche à peau (embrasser)</li><li>😮‍💨 Particules respiratoires (parler ou respirer très près)</li><li>🛏️ Objets contaminés (vêtements, draps)</li><li>🤰 De la mère au bébé pendant la grossesse</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>💉 Se faire vacciner (si disponible, surtout en épidémie)</li><li>🚫 Éviter le contact avec une personne qui a des boutons</li><li>🛏️ Ne pas partager les draps ou vêtements d&#x27;un malade</li><li>💑 Limiter les partenaires sexuels</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur les boutons suspects et les modes de transmission. Encourage les personnes avec des éruptions cutanées à consulter rapidement.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  ebola: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('ebola')\" id=\"tts-btn-ebola\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Après avoir soigné à la maison un proche revenu très malade d&#x27;un pays voisin, Chantal a une fièvre très forte qui arrive d&#x27;un coup, et elle commence à saigner du nez et des gencives sans raison.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"🩸 Saignement\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-saignement\">\n    <path class=\"picto-blooddrop\" d=\"M30 10 C40 26 44 34 34 42 C28 47 22 42 22 36 C22 28 24 22 30 10 Z\" fill=\"#c0392b\"/>\n  </svg><span class=\"picto-label\">🩸 Saignement</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre</strong> — Elle arrive brutalement et est très forte.</li><li><strong>Saignements</strong> — Du sang sort du nez, des gencives, des yeux, ou ailleurs, sans blessure — c&#x27;est un signe très grave.</li><li><strong>Lien avec un malade</strong> — Ce signe apparaît après avoir touché ou soigné une personne déjà malade, ou son corps si elle est décédée.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : fièvre soudaine avec un saignement qu&#x27;on ne peut pas expliquer, OU tout contact avec une personne suspecte de cette maladie. N&#x27;y touche jamais à mains nues — protège-toi et notifie tout de suite.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne présentant une fièvre soudaine avec des saignements inexpliqués, OU ayant eu contact avec un cas suspect d&#x27;Ebola.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🩸 Contact avec les liquides biologiques du malade (sang, sueur, selles, urines, vomissements, lait maternel)</li><li>⚰️ Toucher le corps d&#x27;une personne décédée d&#x27;Ebola</li><li>🦇 Consommer des chauves-souris ou singes morts</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🧼 Lavage fréquent des mains à l&#x27;eau et au savon</li><li>🚫 Ne pas toucher les liquides biologiques des malades</li><li>⚰️ Éviter les rites funéraires avec contact du corps</li><li>🦇 Éloigner les chauves-souris des maisons</li><li>🐒 Ne pas garder de singes à la maison</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur les modes de transmission et la conduite à tenir. Rappelle à la communauté que les rites funéraires avec contact du corps sont très dangereux.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  pfa: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('pfa')\" id=\"tts-btn-pfa\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Le petit Fabrice, 4 ans, jouait normalement hier. Ce matin, sa jambe est toute molle, il n&#x27;arrive plus à se tenir debout, et il n&#x27;est ni tombé ni ne s&#x27;est blessé.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🦵 Faiblesse d’un membre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-faiblesse\">\n    <circle cx=\"30\" cy=\"14\" r=\"7\" fill=\"#fde3e0\"/>\n    <rect x=\"27\" y=\"20\" width=\"6\" height=\"16\" fill=\"#fde3e0\"/>\n    <rect x=\"27\" y=\"36\" width=\"6\" height=\"4\" fill=\"#fde3e0\"/>\n    <path class=\"picto-leg\" d=\"M30 40 q10 4 8 16\" stroke=\"#fde3e0\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\"/>\n    <rect x=\"18\" y=\"36\" width=\"6\" height=\"4\" fill=\"#fde3e0\"/>\n    <path d=\"M21 40 q-6 2 -6 14\" stroke=\"#fde3e0\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\"/>\n  </svg><span class=\"picto-label\">🦵 Faiblesse d’un membre</span></div><div class=\"picto-item\" title=\"😴 Fatigue\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fatigue\">\n    <circle cx=\"26\" cy=\"32\" r=\"14\" fill=\"#e3f0ff\"/>\n    <path d=\"M20 32 h6\" stroke=\"#1c1c2e\" stroke-width=\"2\"/>\n    <path d=\"M32 32 h6\" stroke=\"#1c1c2e\" stroke-width=\"2\"/>\n    <text x=\"40\" y=\"20\" font-size=\"10\" fill=\"#1565c0\" class=\"picto-zzz z1\">z</text>\n    <text x=\"46\" y=\"14\" font-size=\"8\" fill=\"#1565c0\" class=\"picto-zzz z2\">z</text>\n    <text x=\"50\" y=\"9\" font-size=\"6\" fill=\"#1565c0\" class=\"picto-zzz z3\">z</text>\n  </svg><span class=\"picto-label\">😴 Fatigue</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Un bras ou une jambe</strong> — D&#x27;un coup, le bras ou la jambe d&#x27;un enfant devient tout mou et faible, comme s&#x27;il n&#x27;avait plus de force du tout dedans. L&#x27;enfant n&#x27;arrive plus à s&#x27;en servir normalement.</li><li><strong>Pas de blessure</strong> — Ça arrive sans chute, sans accident, sans coup — le membre devient faible tout seul.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : chez un enfant de moins de 15 ans, une faiblesse soudaine d&#x27;un bras ou d&#x27;une jambe, sans accident. Un seul cas suffit pour alerter tout de suite, comme pour le choléra.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Tout enfant de moins de 15 ans qui présente soudainement une faiblesse ou incapacité à bouger un bras ou une jambe, sans notion de traumatisme (choc/accident). ⚠️ Un seul cas = cas alerte !\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🥤 Eau ou aliments contaminés par les selles d&#x27;une personne infectée</li><li>💩 Voie oro-fécale (selles → bouche)</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>💉 Vacciner tous les enfants contre la polio (VPO à 6, 10 et 14 semaines)</li><li>🧼 Se laver les mains à l&#x27;eau et au savon</li><li>🚽 Utiliser des latrines propres</li><li>🍽️ Bien cuire les aliments et traiter l&#x27;eau</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Encourage la vaccination des enfants, aide à détecter rapidement les cas de paralysie suspecte et sensibilise sur l&#x27;hygiène.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  rage: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('rage')\" id=\"tts-btn-rage\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Un chien errant mord Sourou pendant qu&#x27;il gardait les moutons. Deux semaines après, Sourou a peur de l&#x27;eau, mal à la tête, et sent des picotements bizarres à l&#x27;endroit où il a été mordu.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"🤕 Maux de tête\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-maux\">\n    <circle cx=\"30\" cy=\"30\" r=\"16\" fill=\"#fde3e0\"/>\n    <path class=\"picto-bolt\" d=\"M32 14 l-6 12 h6 l-6 12\" stroke=\"#e67e22\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  </svg><span class=\"picto-label\">🤕 Maux de tête</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>La morsure ou griffure</strong> — Un animal (chien, chat, singe...) a mordu, griffé, ou léché une plaie ou les yeux de la personne.</li><li><strong>Après la morsure</strong> — La personne a peur, est angoissée, a mal à la tête, de la fièvre, ou sent des picotements bizarres autour de l&#x27;endroit mordu.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : une morsure, griffure, ou léchage par un animal, avec ensuite de l&#x27;angoisse, des maux de tête, de la fièvre, ou des sensations bizarres près de la blessure. Il ne faut jamais attendre — laver la plaie tout de suite à l&#x27;eau et au savon et référer.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne ayant été mordue, griffée ou léchée sur une plaie par un animal (chien, chat, singe…) ET qui présente angoisse, maux de tête, fièvre ou sensations anormales près de la blessure.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🐕 Morsure d&#x27;un animal enragé (chien surtout au Bénin)</li><li>🐱 Griffure ou léchage d&#x27;une plaie par un animal enragé</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>💉 Vacciner les chiens, chats et singes domestiques</li><li>🧼 Laver abondamment la plaie à l&#x27;eau et au savon après morsure</li><li>🏥 Se rendre immédiatement au centre de santé après toute morsure</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur la vaccination des animaux domestiques et l&#x27;importance de consulter immédiatement après une morsure. Encourage les propriétaires à mettre leurs animaux sous surveillance.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  rougeole: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('rougeole')\" id=\"tts-btn-rougeole\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">La petite Rachidatou a de la fièvre depuis 2 jours. Aujourd&#x27;hui, des petits boutons rouges apparaissent sur son visage, puis descendent sur tout son corps.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"🌡️ Fièvre\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-fievre\">\n    <rect x=\"26\" y=\"8\" width=\"8\" height=\"30\" rx=\"4\" fill=\"#fde3e0\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"9\" fill=\"#fde3e0\"/>\n    <rect x=\"28\" y=\"30\" width=\"4\" height=\"14\" rx=\"2\" fill=\"#c0392b\" class=\"picto-mercury\"/>\n    <circle cx=\"30\" cy=\"44\" r=\"5.5\" fill=\"#c0392b\" class=\"picto-bulb\"/>\n    <path class=\"picto-wave\" d=\"M10 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n    <path class=\"picto-wave picto-wave2\" d=\"M42 14 q4 -6 8 0 t8 0\" stroke=\"#e67e22\" stroke-width=\"2\" fill=\"none\"/>\n  </svg><span class=\"picto-label\">🌡️ Fièvre</span></div><div class=\"picto-item\" title=\"🔴 Éruption cutanée\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-eruption\">\n    <ellipse cx=\"30\" cy=\"32\" rx=\"18\" ry=\"20\" fill=\"#fde3e0\"/>\n    <circle cx=\"20\" cy=\"20\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d1\"/>\n    <circle cx=\"34\" cy=\"16\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d2\"/>\n    <circle cx=\"42\" cy=\"28\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d3\"/>\n    <circle cx=\"18\" cy=\"36\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d4\"/>\n    <circle cx=\"30\" cy=\"42\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d5\"/>\n    <circle cx=\"40\" cy=\"42\" r=\"3\" fill=\"#c0392b\" class=\"picto-dot d6\"/>\n  </svg><span class=\"picto-label\">🔴 Éruption cutanée</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Fièvre</strong> — Elle dure déjà depuis quelques jours.</li><li><strong>Boutons rouges sur la peau</strong> — Des petits boutons rouges (éruption) apparaissent d&#x27;abord sur le visage, puis se répandent sur tout le corps.</li><li><strong>Yeux et nez</strong> — Souvent, les yeux sont rouges et le nez coule.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : fièvre ET boutons rouges sur le corps, surtout chez un enfant.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne (surtout enfant) présentant de la fièvre ET des éruptions cutanées (boutons rouges) sur le corps.\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>💨 Par l&#x27;air (toux, éternuements du malade)</li><li>🤝 Contact rapproché avec une personne malade</li><li>🤧 Contact avec les sécrétions nasales d&#x27;un malade</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>💉 Vacciner les enfants : RR1 à 9 mois, RR2 (rappel) 6 mois après</li><li>😷 Hygiène respiratoire (tousser dans le coude)</li><li>🏠 Éviter la surpopulation</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Encourage la vaccination des enfants et sensibilise sur l&#x27;isolement du cas pour éviter la propagation dans la communauté.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  shigellose: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('shigellose')\" id=\"tts-btn-shigellose\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Après avoir mangé au bord de la route, Elvire a très mal au ventre et va souvent aux toilettes, avec du sang et du mucus (comme de la glaire) mélangés dans les selles.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        <div class=\"picto-strip\"><div class=\"picto-item\" title=\"💩 Diarrhée\">\n  <svg viewBox=\"0 0 60 60\" class=\"picto picto-diarrhee\">\n    <ellipse cx=\"30\" cy=\"46\" rx=\"16\" ry=\"6\" fill=\"#d9e6f2\"/>\n    <rect x=\"16\" y=\"10\" width=\"28\" height=\"4\" fill=\"#8ba3bd\"/>\n    <path d=\"M18 14 v14\" stroke=\"#8ba3bd\" stroke-width=\"3\"/>\n    <path d=\"M42 14 v14\" stroke=\"#8ba3bd\" stroke-width=\"3\"/>\n    <path class=\"picto-drop\" d=\"M30 20 q4 6 0 10 q-4 -4 0 -10 z\" fill=\"#1565c0\"/>\n    <path class=\"picto-drop picto-drop2\" d=\"M22 22 q3 5 0 8 q-3 -3 0 -8 z\" fill=\"#1565c0\"/>\n    <path class=\"picto-drop picto-drop3\" d=\"M38 22 q3 5 0 8 q-3 -3 0 -8 z\" fill=\"#1565c0\"/>\n  </svg><span class=\"picto-label\">💩 Diarrhée</span></div></div>\n        <ul class=\"scene-list symptom-list\"><li><strong>Le ventre</strong> — Des crampes et des douleurs fortes dans le ventre.</li><li><strong>Les selles</strong> — La diarrhée contient du sang et du mucus (une matière visqueuse, comme de la glaire) — ce n&#x27;est pas juste de l&#x27;eau comme pour le choléra.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : mal au ventre ET diarrhée avec du sang et du mucus dans les selles.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"Toute personne souffrant de douleurs de ventre ET de diarrhée avec du sang et du mucus (glairo-sanguinolente).\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <ul class=\"scene-list\"><li>🤲 Mauvaise hygiène des mains (mains sales)</li><li>🥤 Eau ou aliments contaminés par les selles</li><li>🪰 Les mouches transportent le germe des selles aux aliments</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🧼 Se laver les mains après toilettes, avant manger et avant cuisiner</li><li>🚽 Utiliser des latrines avec dispositif de lavage des mains</li><li>🍽️ Protéger les aliments (couvrir pour éviter les mouches)</li><li>💧 S&#x27;approvisionner en eau potable</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Sensibilise sur le lavage des mains, l&#x27;utilisation des latrines et la protection des aliments. Décourage fortement l&#x27;automédication.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
  deces: "<div class=\"tts-bar\">\n        <button class=\"tts-btn\" onclick=\"toggleSpeech('deces')\" id=\"tts-btn-deces\">🔊 Écouter le script</button>\n      </div>\n\n      <div class=\"scene scene-example\">\n        <div class=\"scene-title\">🏘️ Exemple de cas dans un village</div>\n        <p class=\"scene-quote\">Une femme enceinte de 8 mois du village décède brutalement à la maison, avant même d&#x27;arriver au centre de santé. Ou bien : un bébé né depuis seulement 10 jours décède à la maison sans qu&#x27;on comprenne pourquoi.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🩺 Comment reconnaître ce cas ? (par partie du corps)</div>\n        \n        <ul class=\"scene-list symptom-list\"><li><strong>Décès d&#x27;une femme</strong> — Toute femme qui décède pendant qu&#x27;elle est enceinte, pendant l&#x27;accouchement, ou dans les 6 semaines après avoir accouché — pour une cause liée à la grossesse (pas un accident).</li><li><strong>Décès d&#x27;un nouveau-né</strong> — Tout bébé qui décède entre sa naissance et ses 28 jours de vie, quelle que soit la cause.</li></ul>\n      </div>\n\n      <div class=\"scene scene-alert\">\n        <div class=\"scene-title\">🚨 Ce qu'il faut retenir (définition du cas alerte)</div>\n        <p class=\"alert-simple\">Retiens surtout : toute femme enceinte qui décède, toute femme qui décède dans les 6 semaines après l&#x27;accouchement, ou tout bébé de 0 à 28 jours qui décède. Chaque cas doit être signalé pour comprendre ce qui s&#x27;est passé et éviter que ça se reproduise.</p>\n        <p class=\"alert-box\">Phrase officielle à répéter 2 fois à l'écran&nbsp;: \"🤰 Toute femme enceinte qui décède 👩 Toute femme qui vient d&#x27;accoucher et qui décède dans les 6 semaines 👶 Tout bébé de 0 à 28 jours qui décède\"</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🔄 Comment ça se transmet ?</div>\n        <p>Parce que le Bénin a encore beaucoup de décès maternels et néonatals qui peuvent souvent être évités si les femmes sont suivies correctement pendant la grossesse et l&#x27;accouchement. En les signalant, on aide à trouver les causes et à améliorer les soins.</p>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">🛡️ Comment prévenir ?</div>\n        <ul class=\"scene-list\"><li>🏥 Encourager toutes les femmes à faire leurs consultations prénatales (CPN)</li><li>🤱 Encourager l&#x27;accouchement dans un centre de santé</li><li>📅 Encourager les visites postnatales dans les jours après l&#x27;accouchement</li><li>🩺 Référer rapidement tout signe de danger chez la femme enceinte ou le nouveau-né</li></ul>\n      </div>\n\n      <div class=\"scene\">\n        <div class=\"scene-title\">⚡ Que faire face à un cas ? (CAT du RC)</div>\n        <ol class=\"cat-list\">\n          <li>Ne prends aucune décision seul(e).</li>\n          <li>Notifie immédiatement l'ASCQ.</li>\n          <li>Réfère le cas au centre de santé.</li>\n          <li>Sensibilise la famille et la communauté.</li>\n        </ol>\n      </div>\n\n      <div class=\"scene scene-close\">\n        <div class=\"scene-title\">👤 Message de clôture (rôle du RC)</div>\n        <p class=\"scene-quote\">\"Encourage toutes les femmes enceintes à faire leurs consultations prénatales, à accoucher dans un centre de santé, et à revenir pour le suivi post-natal. Détecte et signale tout décès maternel ou néonatal dans sa zone.\"</p>\n        <p class=\"closing-line\">Phrase finale à dire face caméra&nbsp;: \"Tu es les yeux et les oreilles du système de santé. Dès qu'un signe suspect apparaît, notifie immédiatement l'ASCQ&nbsp;!\"</p>\n      </div>",
};

const BRIEFING_VIDEO_TTS = {
  anthrax: "Maladie : Anthrax (Maladie du Charbon). Exemple de cas : Dans un village de l'Atacora, Toussaint élève des bœufs. Un matin, une de ses vaches meurt d'un coup et gonfle très vite. Sans faire inspecter la viande, il la découpe pour la vendre au marché. Trois jours après, une petite plaie noire apparaît sur sa main et grossit, avec de la fièvre. Comment reconnaître ce cas ? Sur la peau : Un petit bouton apparaît (souvent sur la main ou le bras), il devient noir comme du charbon et gonfle autour. Ça ne fait pas très mal, mais ça grossit vite. Dans le ventre : La personne a mal au ventre, vomit, n'a plus faim, et a de la fièvre. Pour respirer : La personne a du mal à respirer, comme si l'air manquait, avec une très forte fièvre. Dans la tête : La fièvre monte d'un coup, le corps se met à trembler fort (on appelle ça des convulsions), et la personne peut perdre connaissance. En résumé : Retiens surtout : toute personne qui travaille avec des animaux (éleveur, boucher, agriculteur) et qui a une plaie noire sur la peau, ou une forte fièvre avec le corps qui tremble, ou du mal à respirer. Comment ça se transmet ? Manger de la viande contaminée Respirer des poussières infectées (champs) Toucher des animaux ou tissues infectés Comment prévenir ? Vacciner les animaux (herbivores, porcs) Inspecter la viande avant de la manger ou vendre Interdire l'accès aux champs contaminés Porter un masque lors des travaux à risque Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise les éleveurs, bouchers et agriculteurs sur les modes de transmission, les symptômes et les moyens de prévention. Rappelle la nécessité d'inspecter toute viande avant de la consommer ou la vendre.",
  covid: "Maladie : COVID-19 (Coronavirus). Exemple de cas : À Cotonou, dans un quartier populaire, Sika a de la fièvre depuis 2 jours. Elle tousse beaucoup, a mal à la gorge, et elle ne sent plus l'odeur de son plat préféré. Comment reconnaître ce cas ? Fièvre : Le corps est chaud, on transpire ou on frissonne. Toux et gorge : La personne tousse souvent et a mal quand elle avale. Nez : Le nez coule ou est bouché, comme un gros rhume. Odorat et goût : La personne ne sent plus les odeurs et ne reconnaît plus le goût de la nourriture. Ventre : Parfois, la personne a la diarrhée (selles liquides). En résumé : Retiens surtout : fièvre + au moins un de ces signes (toux, rhume, mal de gorge, perte de l'odorat ou du goût, diarrhée). Comment ça se transmet ? Postillons et gouttelettes en parlant, toussant, éternuant Toucher des surfaces contaminées puis se toucher le visage Contact avec les yeux, le nez ou la bouche Comment prévenir ? Se laver les mains souvent à l'eau et au savon Porter un masque hors de la maison Garder 1 mètre de distance avec les autres Tousser dans le coude, pas dans la main Éviter les grands rassemblements Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur les gestes barrières, surveille les ménages, communique le numéro 136, et identifie les personnes revenues de voyage récemment.",
  cholera: "Maladie : Choléra. Exemple de cas : Après un mariage au village où l'eau du puits n'était pas propre, Akpédjè commence soudainement à aller aux toilettes très souvent, avec des selles toutes liquides comme de l'eau de riz. Elle est très fatiguée et a très soif. Comment reconnaître ce cas ? Selles (aller aux toilettes) : La personne va aux toilettes 3 fois ou plus en une seule journée, avec des selles complètement liquides, comme de l'eau — pas des selles normales. Fatigue et soif : La personne se sent très faible, très fatiguée, et a énormément soif car son corps perd beaucoup d'eau. En résumé : Retiens surtout : 3 selles liquides ou plus en une journée. C'est très grave et très contagieux — un seul cas suffit pour alerter tout de suite, il ne faut pas attendre d'autres cas. Comment ça se transmet ? Eau contaminée Aliments souillés (non lavés ou mal cuits) Contact avec une personne infectée (selles) Comment prévenir ? Se laver les mains à l'eau et au savon avant de manger et après les toilettes Utiliser des latrines pour faire ses besoins Traiter l'eau de boisson avant de la consommer Bien cuire les aliments Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur le lavage des mains, encourage le traitement de l'eau de boisson, et promeut l'utilisation des latrines dans chaque ménage.",
  dengue: "Maladie : Dengue. Exemple de cas : En saison des pluies, près d'une flaque d'eau où les moustiques pondent, Comlan attrape d'un coup une très forte fièvre, avec des douleurs partout dans le corps (muscles et articulations) comme s'il avait été battu. Comment reconnaître ce cas ? Fièvre : Elle arrive d'un coup et monte très haut. Douleurs du corps : Les muscles et les articulations (genoux, coudes, poignets) font très mal, comme après un gros effort ou une bagarre. Tête et yeux : Souvent, mal à la tête et derrière les yeux. En résumé : Retiens surtout : fièvre soudaine + fortes douleurs dans le corps, surtout en période où il y a beaucoup de moustiques. Comment ça se transmet ? Piqûre du moustique Aedes aegypti (moustique tigre) infecté → Ce moustique pique surtout le matin et le soir. Il pond ses œufs dans les eaux stagnantes (vieux pneus, canaris, bidons). Comment prévenir ? Éliminer les eaux stagnantes autour des maisons Dormir sous moustiquaire imprégnée (MIILD) Mettre des grillages aux portes et fenêtres Débroussailler autour des maisons Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur les moustiques et les eaux stagnantes. Encourage l'utilisation des moustiquaires dans tous les foyers.",
  fj: "Maladie : Fièvre Jaune. Exemple de cas : Blaise, agriculteur qui n'a jamais été vacciné, a une fièvre qui arrive d'un coup. Quelques jours après, ses yeux et sa peau deviennent jaunes. Comment reconnaître ce cas ? Fièvre : Elle commence brutalement, d'un seul coup. Yeux et peau : Après quelques jours, le blanc des yeux devient jaune, puis la peau aussi devient jaune. On appelle ça la jaunisse. En résumé : Retiens surtout : fièvre soudaine suivie, dans les 14 jours, d'une jaunisse (yeux et peau jaunes). Comment ça se transmet ? Piqûre de moustique infecté (genre Aedes) Peut venir des singes en forêt (via moustiques) Comment prévenir ? Se faire vacciner contre la fièvre jaune Éliminer les gîtes à moustiques (eaux stagnantes) Dormir sous moustiquaire (MIILD) Grillages aux portes et fenêtres Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur la vaccination et la lutte contre les moustiques. Encourage chaque famille à dormir sous moustiquaire.",
  grippe: "Maladie : Grippe Aviaire (Grippe d'origine animale). Exemple de cas : Dans un village d'éleveurs de volailles, plusieurs poules meurent d'un coup sans raison. Quelques jours après, Fifamè, qui s'occupe des poules, a de la fièvre, tousse et a du mal à respirer. Comment reconnaître ce cas ? Fièvre et toux : La personne a de la fièvre et tousse beaucoup. Pour respirer : Elle a du mal à respirer, comme si elle manquait d'air. Lien avec les volailles : Ce signe apparaît après avoir touché ou mangé des poules ou canards malades ou morts. En résumé : Retiens surtout : fièvre + toux + difficulté à respirer, après un contact avec des volailles mortes ou malades. Comment ça se transmet ? Contact avec les selles ou sécrétions de volailles infectées Consommer de la volaille ou eau contaminée Toucher des vêtements ou équipements contaminés Comment prévenir ? Tenir les volailles loin des oiseaux sauvages Garder les poulaillers propres Signaler toute mort suspecte de volaille Bien cuire les volailles avant de les manger Se laver les mains après tout contact avec les volailles Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise les éleveurs et commerçants de volailles sur les règles d'hygiène. Surveille et signale immédiatement toute mort massive de volaille dans le quartier.",
  hanta: "Maladie : Hantavirus. Exemple de cas : Un cultivateur qui range son grenier plein de rats et de leurs crottes commence, quelques semaines après, à avoir de la fièvre et des courbatures partout dans le corps. Comment reconnaître ce cas ? Fièvre : Le corps devient chaud. Douleurs et fatigue : La personne a mal partout dans le corps et se sent très faible. Lien avec les rats : Ce signe apparaît après avoir été en contact avec des rats, leurs crottes, ou la poussière d'un endroit où il y a des rats (grenier, grange). En résumé : Retiens surtout : fièvre + un autre signe, chez une personne qui a été en contact avec des rats dans les 45 derniers jours. Comment ça se transmet ? Contact avec l'urine, les selles ou la salive de rongeurs infectés Respirer des poussières contaminées par des rongeurs Morsure de rongeur Comment prévenir ? Garder la maison propre, boucher les trous où les rats peuvent entrer Protéger les aliments contre les rongeurs Humidifier la zone avant de nettoyer (ne pas balayer à sec) Se laver régulièrement les mains à l'eau et au savon Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur les dangers des rongeurs et l'importance de maintenir les habitations propres et sans rats.",
  lassa: "Maladie : Fièvre Hémorragique à Virus Lassa. Exemple de cas : Dans une maison où les rats courent partout et grignotent la nourriture, Mariam tombe malade : elle a de la fièvre, mal à la tête, et elle commence à saigner du nez sans raison. Comment reconnaître ce cas ? Fièvre et fatigue : La personne a de la fièvre, mal à la tête, et se sent très faible. Saignements : Du sang sort du nez, des gencives, ou ailleurs, sans blessure — c'est un signe grave. Lien avec les rats ou un malade : Ce signe apparaît après un contact avec des rats, leur urine ou leurs crottes, ou après avoir touché une personne déjà malade de cette fièvre. En résumé : Retiens surtout : des signes évocateurs, OU un saignement qui n'a pas d'explication, OU un contact avec un malade dans les 21 derniers jours. Comment ça se transmet ? Contact avec les excréments, urine ou salive de rat multimamelles (Mastomys) Contact avec le sang, sueur, selles ou liquides biologiques d'un malade Contact avec le corps d'une personne décédée de Lassa Contact avec chauves-souris ou singes morts en période d'épidémie Comment prévenir ? Lavage systématique des mains à l'eau et au savon Dératiser les maisons, protéger les aliments contre les rats Ne pas toucher les personnes malades ou décédées sans protection Ne pas manipuler ni consommer les chauves-souris ou singes Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur les rats, les liquides biologiques des malades et la conduite à tenir. Encourage la dératisation dans chaque ménage.",
  meningite: "Maladie : Méningite. Exemple de cas : En saison sèche (harmattan), Kokou a une très forte fièvre. Son cou est tout raide et dur : il n'arrive plus à pencher la tête en avant pour toucher sa poitrine avec le menton. Comment reconnaître ce cas ? Fièvre : Elle est très forte. Le cou : Le cou devient raide et dur, la personne ne peut plus baisser la tête vers l'avant. C'est le signe le plus important à reconnaître. En résumé : Retiens surtout : fièvre ET nuque raide (le cou ne plie plus vers l'avant). C'est une urgence — il faut référer très vite. Comment ça se transmet ? Gouttelettes respiratoires (toux, éternuements, postillons) Surpopulation dans les logements Saison sèche (harmattan) favorise la transmission Comment prévenir ? Vaccination antiméningococcique Hygiène des mains et hygiène respiratoire Éviter la surpopulation dans les logements Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Mène des activités de sensibilisation sur la méningite. Encourage la vaccination et le respect des règles d'hygiène respiratoire.",
  mpox: "Maladie : Mpox (Variole du Singe). Exemple de cas : Après avoir chassé et préparé un animal de brousse, Idrissou remarque un bouton bizarre sur sa peau, qui ne ressemble pas à un bouton normal et qui ne guérit pas comme d'habitude. Comment reconnaître ce cas ? Sur la peau : Un ou plusieurs boutons ou plaies apparaissent sur la peau, souvent au visage, aux mains ou aux parties intimes. Ils peuvent ressembler à des cloques ou des croûtes qui ne guérissent pas vite. Fièvre (parfois) : Il peut y avoir de la fièvre avant ou en même temps que les boutons, mais pas toujours. En résumé : Retiens surtout : n'importe quelle éruption de la peau qu'on ne peut pas expliquer, avec ou sans fièvre — même un seul bouton suffit pour alerter, il ne faut pas attendre d'en voir plusieurs. Comment ça se transmet ? Contact peau à peau (toucher, rapports sexuels) Contact bouche à peau (embrasser) Particules respiratoires (parler ou respirer très près) Objets contaminés (vêtements, draps) De la mère au bébé pendant la grossesse Comment prévenir ? Se faire vacciner (si disponible, surtout en épidémie) Éviter le contact avec une personne qui a des boutons Ne pas partager les draps ou vêtements d'un malade Limiter les partenaires sexuels Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur les boutons suspects et les modes de transmission. Encourage les personnes avec des éruptions cutanées à consulter rapidement.",
  ebola: "Maladie : Maladie à Virus Ebola (MVE). Exemple de cas : Après avoir soigné à la maison un proche revenu très malade d'un pays voisin, Chantal a une fièvre très forte qui arrive d'un coup, et elle commence à saigner du nez et des gencives sans raison. Comment reconnaître ce cas ? Fièvre : Elle arrive brutalement et est très forte. Saignements : Du sang sort du nez, des gencives, des yeux, ou ailleurs, sans blessure — c'est un signe très grave. Lien avec un malade : Ce signe apparaît après avoir touché ou soigné une personne déjà malade, ou son corps si elle est décédée. En résumé : Retiens surtout : fièvre soudaine avec un saignement qu'on ne peut pas expliquer, OU tout contact avec une personne suspecte de cette maladie. N'y touche jamais à mains nues — protège-toi et notifie tout de suite. Comment ça se transmet ? Contact avec les liquides biologiques du malade (sang, sueur, selles, urines, vomissements, lait maternel) Toucher le corps d'une personne décédée d'Ebola Consommer des chauves-souris ou singes morts Comment prévenir ? Lavage fréquent des mains à l'eau et au savon Ne pas toucher les liquides biologiques des malades Éviter les rites funéraires avec contact du corps Éloigner les chauves-souris des maisons Ne pas garder de singes à la maison Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur les modes de transmission et la conduite à tenir. Rappelle à la communauté que les rites funéraires avec contact du corps sont très dangereux.",
  pfa: "Maladie : PFA – Paralysie Flasque Aiguë (Polio). Exemple de cas : Le petit Fabrice, 4 ans, jouait normalement hier. Ce matin, sa jambe est toute molle, il n'arrive plus à se tenir debout, et il n'est ni tombé ni ne s'est blessé. Comment reconnaître ce cas ? Un bras ou une jambe : D'un coup, le bras ou la jambe d'un enfant devient tout mou et faible, comme s'il n'avait plus de force du tout dedans. L'enfant n'arrive plus à s'en servir normalement. Pas de blessure : Ça arrive sans chute, sans accident, sans coup — le membre devient faible tout seul. En résumé : Retiens surtout : chez un enfant de moins de 15 ans, une faiblesse soudaine d'un bras ou d'une jambe, sans accident. Un seul cas suffit pour alerter tout de suite, comme pour le choléra. Comment ça se transmet ? Eau ou aliments contaminés par les selles d'une personne infectée Voie oro-fécale (selles → bouche) Comment prévenir ? Vacciner tous les enfants contre la polio (VPO à 6, 10 et 14 semaines) Se laver les mains à l'eau et au savon Utiliser des latrines propres Bien cuire les aliments et traiter l'eau Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Encourage la vaccination des enfants, aide à détecter rapidement les cas de paralysie suspecte et sensibilise sur l'hygiène.",
  rage: "Maladie : Rage. Exemple de cas : Un chien errant mord Sourou pendant qu'il gardait les moutons. Deux semaines après, Sourou a peur de l'eau, mal à la tête, et sent des picotements bizarres à l'endroit où il a été mordu. Comment reconnaître ce cas ? La morsure ou griffure : Un animal (chien, chat, singe...) a mordu, griffé, ou léché une plaie ou les yeux de la personne. Après la morsure : La personne a peur, est angoissée, a mal à la tête, de la fièvre, ou sent des picotements bizarres autour de l'endroit mordu. En résumé : Retiens surtout : une morsure, griffure, ou léchage par un animal, avec ensuite de l'angoisse, des maux de tête, de la fièvre, ou des sensations bizarres près de la blessure. Il ne faut jamais attendre — laver la plaie tout de suite à l'eau et au savon et référer. Comment ça se transmet ? Morsure d'un animal enragé (chien surtout au Bénin) Griffure ou léchage d'une plaie par un animal enragé Comment prévenir ? Vacciner les chiens, chats et singes domestiques Laver abondamment la plaie à l'eau et au savon après morsure Se rendre immédiatement au centre de santé après toute morsure Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur la vaccination des animaux domestiques et l'importance de consulter immédiatement après une morsure. Encourage les propriétaires à mettre leurs animaux sous surveillance.",
  rougeole: "Maladie : Rougeole. Exemple de cas : La petite Rachidatou a de la fièvre depuis 2 jours. Aujourd'hui, des petits boutons rouges apparaissent sur son visage, puis descendent sur tout son corps. Comment reconnaître ce cas ? Fièvre : Elle dure déjà depuis quelques jours. Boutons rouges sur la peau : Des petits boutons rouges (éruption) apparaissent d'abord sur le visage, puis se répandent sur tout le corps. Yeux et nez : Souvent, les yeux sont rouges et le nez coule. En résumé : Retiens surtout : fièvre ET boutons rouges sur le corps, surtout chez un enfant. Comment ça se transmet ? Par l'air (toux, éternuements du malade) Contact rapproché avec une personne malade Contact avec les sécrétions nasales d'un malade Comment prévenir ? Vacciner les enfants : RR1 à 9 mois, RR2 (rappel) 6 mois après Hygiène respiratoire (tousser dans le coude) Éviter la surpopulation Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Encourage la vaccination des enfants et sensibilise sur l'isolement du cas pour éviter la propagation dans la communauté.",
  shigellose: "Maladie : Shigellose (Diarrhée Sanglante). Exemple de cas : Après avoir mangé au bord de la route, Elvire a très mal au ventre et va souvent aux toilettes, avec du sang et du mucus (comme de la glaire) mélangés dans les selles. Comment reconnaître ce cas ? Le ventre : Des crampes et des douleurs fortes dans le ventre. Les selles : La diarrhée contient du sang et du mucus (une matière visqueuse, comme de la glaire) — ce n'est pas juste de l'eau comme pour le choléra. En résumé : Retiens surtout : mal au ventre ET diarrhée avec du sang et du mucus dans les selles. Comment ça se transmet ? Mauvaise hygiène des mains (mains sales) Eau ou aliments contaminés par les selles Les mouches transportent le germe des selles aux aliments Comment prévenir ? Se laver les mains après toilettes, avant manger et avant cuisiner Utiliser des latrines avec dispositif de lavage des mains Protéger les aliments (couvrir pour éviter les mouches) S'approvisionner en eau potable Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Sensibilise sur le lavage des mains, l'utilisation des latrines et la protection des aliments. Décourage fortement l'automédication.",
  deces: "Maladie : Décès Maternels & Décès Néonatals. Exemple de cas : Une femme enceinte de 8 mois du village décède brutalement à la maison, avant même d'arriver au centre de santé. Ou bien : un bébé né depuis seulement 10 jours décède à la maison sans qu'on comprenne pourquoi. Comment reconnaître ce cas ? Décès d'une femme : Toute femme qui décède pendant qu'elle est enceinte, pendant l'accouchement, ou dans les 6 semaines après avoir accouché — pour une cause liée à la grossesse (pas un accident). Décès d'un nouveau-né : Tout bébé qui décède entre sa naissance et ses 28 jours de vie, quelle que soit la cause. En résumé : Retiens surtout : toute femme enceinte qui décède, toute femme qui décède dans les 6 semaines après l'accouchement, ou tout bébé de 0 à 28 jours qui décède. Chaque cas doit être signalé pour comprendre ce qui s'est passé et éviter que ça se reproduise. Comment ça se transmet ? Parce que le Bénin a encore beaucoup de décès maternels et néonatals qui peuvent souvent être évités si les femmes sont suivies correctement pendant la grossesse et l'accouchement. En les signalant, on aide à trouver les causes et à améliorer les soins. Comment prévenir ? Encourager toutes les femmes à faire leurs consultations prénatales (CPN) Encourager l'accouchement dans un centre de santé Encourager les visites postnatales dans les jours après l'accouchement Référer rapidement tout signe de danger chez la femme enceinte ou le nouveau-né Que faire face à un cas ? Ne prends aucune décision seul. Notifie immédiatement l'ASCQ. Réfère le cas au centre de santé. Sensibilise la famille et la communauté. Encourage toutes les femmes enceintes à faire leurs consultations prénatales, à accoucher dans un centre de santé, et à revenir pour le suivi post-natal. Détecte et signale tout décès maternel ou néonatal dans sa zone.",
};
